\section{Preliminaries}
\label{prelims}
All logarithms in this paper are to the base of $2$. 
Throughout the paper, we use the $\tilde O(\cdot)$ notation to hide multiplicative factors that are polynomial in $\log m$ and $\log n$, where $m$ and $n$ are the number of edges and vertices, respectively, in the initial input graph.
All graphs in this paper are undirected. By default, we allow parallel edges but we do not allow self loops. Graphs in which parallel edges are not allowed are explicitly referred to as \emph{simple} graphs.

We follow standard graph-theoretic notation.   Given a graph $G=(V,E)$ and two disjoint subsets $A,B$ of its vertices, we denote by $E_G(A,B)$ the set of all edges with one endpoint in $A$ and another in $B$, and by $E_G(A)$ the set of all edges with both endpoints in $A$. We also denote by $\delta_G(A)$ the set of all edges with exactly one endpoint in $A$. For a vertex $v\in V(G)$, we denote by $\delta_G(v)$ the set of all edges incident to $v$ in $G$, and by $\deg_G(v)$ the degree of $v$ in $G$.
We also denote by $\vdeg_G$ the $n$-dimensional vector of all vertex degrees in $G$.
We may omit the subscript $G$ when clear from context. Given a subset $S\subseteq V$ of vertices of $G$, we denote by $G[S]$ the subgraph of $G$ induced by $S$.

If $G$ is a graph, and $\pset$ is a collection of paths in $G$, we say that the paths in $\pset$ cause \emph{congestion $\eta$}, if every edge $e\in E(G)$ participates in at most $\eta$ paths in $\pset$, and some edge participates in exactly $\eta$ such paths.

Assume now that we are given a graph $G$  with capacities $c(e)> 0$ on edges $e\in E(G)$. 
A \emph{flow} in $G$ is an assignment of non-negative flow values $f(P)$ to paths $P$ in $G$. If $P$ is a path whose corresponding flow value $f(P)$ is non-zero, then we say that $P$ is a \emph{flow-path}. A flow $f$ is typically defined by providing a list of flow-paths $P$ together with their corresponding flow value $f(P)$. For an edge $e\in E(G)$, the flow $f(e)$ through  $e$ is the total sum of flow values $f(P)$ over all paths $P$ containing $e$. We say that flow $f$ causes {\em congestion} $\eta$ if $\max_{e\in E(G)}\set{\frac{f(e)}{c(e)}}=\eta$.
Notice that it is possible that $\eta<1$. If $f(e)\leq c(e)$ holds for every edge $e\in E(G)$, we may sometimes say that $f$ is a \emph{valid flow}, or that it \emph{respects edge capacities}. When the edge capacities $c(e)$ are not explicitly given, we assume that they are unit.

\paragraph{Embeddings of Graphs.}
Let $G$, $X$ be two graphs with $|V(X)|\leq |V(G)|$. An \emph{embedding} of $X$ into $G$ consists of a mapping $g:V(X)\rightarrow V(G)$, such that the vertices of $X$ are mapped to {\bf distinct} vertices of $G$, and a collection $\pset=\set{P(e)\mid e\in E(X)}$ of paths in graph $G$, such that, for every edge $e=(x,y)\in E(X)$, path $P(e)$ connects $g(x)$ to $g(y)$. The \emph{congestion} of the embedding is the maximum, over all edges $e'\in E(G)$, of the number of paths in $\pset$ containing $e'$. Given an embedding of $X$ into $G$ as above, we will often identify vertices $v\in V(X)$ with the corresponding vertices $g(v)\in V(G)$ to which they are mapped, and so the embedding will only be specified by the collection $\pset$ of embedding paths. Whenever we say that we are given an embedding of a graph $X$ into a graph $G$, this implicitly means that $|V(X)|\leq |V(G)|$.

\subsection{Vertex Weighting, Conductance and Expanders}

Given an $n$-vertex graph $G=(V,E)$,
a \emph{vertex weighting} $w: V \mapsto \mathbb{Z}_{\geq 0}$ is an assignment of non-negative integral weight $w(v)$ to every vertex $v\in V(G)$. We denote by $\vw$ the corresponding $n$-dimensional vector of all vertex weights.
We may sometimes consider two special vertex weightings: weighting $\vdeg_G$, where the weight of every vertex $v$ is $\deg_G(v)$; and a weighting $\vDelta$, where $\Delta>0$ is an real number, and $\vDelta$ is an $n$-dimensional vector with all entries equal to $\Delta$, so the weight of every vertex is $\Delta$.

\subsection{Demands and their Routing}
\label{subsec: demands}

\begin{definition}[$\vw$-restricted demand]\label{def: restricted demand}
	Let $G=(V,E)$ be a graph, and let $\vw$ be a weighting of its vertices. A \emph{demand} in $G$ consists of a collection $\Pi$ of pairs of vertices, and, for every pair $(a,b)\in \Pi$, a value $D(a,b)>0$, that we refer to as the \emph{demand between $a$ and $b$}. We say that a demand $\dset=\left(\Pi,\set{D(a,b)}_{(a,b)\in \Pi}\right )$ is
	\emph{$\vw$-restricted}, if, for every vertex $v\in V$, the total demand between all pairs in $\Pi$ that contain $v$ is at most $w(v)$.
	When $\vw=\vDelta$ for an integer $\Delta$, we may sometimes refer to a $\vw$-resticted demand as  a \emph{$\Delta$}-restricted demand. 

	 The \emph{support} of the demand $\dset=\left(\Pi,\set{D(a,b)}_{(a,b)\in \Pi}\right )$ is the set of all vertices participating in the pairs in $\Pi$. We say that the demand is between two pairs $A,B\subseteq V$  of subsets of vertices of $G$, if $\Pi\subseteq A\times B$.
\end{definition}

\begin{definition}[Routing of a demand]\label{def: routing}
	Let $G=(V,E)$ be a graph,  and let $\dset=\left(\Pi,\set{D(a,b)}_{(a,b)\in \Pi}\right )$  be a demand in $G$. For every pair $(a,b)\in \Pi$, let $\pset_{a,b}$ denote the collection of all $a$-$b$ paths in $G$. A \emph{fractional routing}, or just a routing, of the demand $\dset$, is a flow $f$, that assigns non-zero values $f(P)>0$ only to flow-paths $P\in \bigcup_{(a,b)\in \Pi}\pset_{a,b}$, such that, for all $(a,b)\in \Pi$, $\sum_{P\in \pset_{a,b}}f(P)=D(a,b)$. The routing is defined by only specifying values $f(P)$ that are non-zero. The \emph{congestion} of the routing is the congestion caused by the flow $f$ in $G$. We say that the routing is \emph{over paths of length at most $d$}, if every flow-path $P$ with $f(P)>0$ has length at most $d$. If, for every path $P$, $f(P)\in\set{0,1}$, then we say that the routing is \emph{integral}. In this case, we may represent the routing as a collection of paths $\qset=\set{P\mid f(P)=1}$
\end{definition}

\subsection{Routers}
\label{subsec: routers}

\begin{definition}[$(\vw,d,\eta)$-Router.]\label{def: router}
	Let $G=(V,E)$ be a graph, let $\vw$ be a weighting of its vertices, and let $S\subseteq V$ be a subset of vertices of $G$. Additionally,  let $d,\eta \geq 1$ be parameters. We say that $G$ is a \emph{$(\vw,d,\eta)$-router} for the set $S$ of supported vertices, if every $\vw$-restricted demand $\dset$ defined over the vertices of $S$ can be routed with congestion at most $\eta$ in $G$, via paths of length at most $d$. \end{definition}

\section{First Tool: a Nice Router and its Pruning}
\label{sec: nice router}

\subsection{Construction of a Nice Router Graph}
We assume that we are given three integral parameters:  $k\geq 256$, $N\geq k^{3k}$, and $\Delta\geq 4k^2$. We sometimes refer to $\Delta$ the \emph{target degree}. We now describe a construction of a corresponding router, that we denote by $W_k^{N,\Delta}$. To avoid clutter, in the remainder of this section, we assume that $N$ and $\Delta$ are fixed, and we do not include them in superscripts, so in this section we denote graph $W_k^{N,\Delta}$ by $W_k$.
The construction of graph $W_k$ is recursive. We start by constructing  a graph $W_1$, and then, for $1< i\leq k$, we construct graph $W_i$ by combining $N$ copies of graph $W_{i-1}$. Parameters $N$ and $\Delta$ remain unchanged for these graphs.

\paragraph{Graph $W_i$ -- a High Level View.}
Consider an integer $1\leq i\leq k$. We now provide a high-level description of graph $W_i=(V_i,E_i)$. The set $V_i$ contains exactly $N^i$ vertices, and it is partitioned into two subsets: set $V_i^c$ of $N^{i-1}$ vertices called \emph{center} vertices, and set $V_i^{\ell}=V_i\setminus V_i^c$ of remaining vertices, called \emph{leaf} vertices. The set $E(W_i)$ of edges of the graph is partitioned into $i$ subsets $E^i_1,\ldots,E^i_i$, where for $1\leq z\leq i$, we refer to the edges of $E^i_z$ as \emph{level-$z$ edges}. If we let $H_z=G_i[E^i_z]$ be the subgraph of $G_i$ induced by the set $E^i_z$ of level-$z$ edges, and denote by $\rset_z$ the collection of the connected components of $H_z$, then each such connected component $C\in \rset_z$ contains exactly $N$ vertices, out of which exactly one is a center vertex. Additionally, if we let $S$ be a star defined over the vertices of $C$, whose center is the unique  vertex of $V(C)\cap V_i^c$, then $C$ can be obtained from $S$ by replacing every edge of $S$ with $\Delta$ parallel copies (we refer to these copies as a \emph{bundle}; the edges of $S$ are referred to as \emph{superedges}). We denote by $\sset_z$ a collection of star graphs that contains, for every connected component $C\in \rset_z$, the corresponding star graph $S$ on $V(C)$ (without the parallel edges). Note that every edge in $W_i$ connects a leaf vertex to a center vertex.
We now describe the construction of the graph $W_i$ in more detail. The construction is recursive, from smaller to larger values of $i$.

\paragraph{Graph $W_1$.}
The set of vertices of the graph $W_1$ is $V_1=\set{v_1,\ldots,v_N}$, where vertex $v_1$ is the \emph{center} vertex, and vertices $v_2,\ldots,v_N$ are \emph{leaf vertices}.
In other words, $V_1^c=\set{v_1}$, and $V_1^{\ell}=\set{v_2,\ldots,v_N}$.
 Let $S$ be a star defined on the vertices of $V_1$, whose center is vertex $v_1$, and leaves are $v_2,\ldots,v_N$. Graph $W_1$ is obtained from $S$ by replacing every edge of $S$ with a collection of $\Delta$ parallel edges. All edges of $W_1$ belong to level $1$, so $E(W_1)=E_1^1$. The collection $\sset_1$ of level-$1$ stars contains a single star $S$.

\paragraph{Graph $W_i$ for $i>1$.}
We assume that we are given an integer $i>1$, and that we have already defined the graph $W_{i-1}$. We now describe the construction of graph $W_i$.

We start by creating $N$ copies of graph $W_{i-1}$, that we denote by $C_1,\ldots,C_N$. We refer to $C_1,\ldots,C_N$ as \emph{level-$(i-1)$ clusters}. We let the set $V_i$ of vertices of $W_i$ be $\bigcup_{j=1}^NV(C_j)$. For all $1\leq j\leq N$, if $v\in V(C_j)$ is a center vertex for $C_j$, then it becomes a center vertex for $W_i$, and otherwise it becomes a leaf vertex for $W_i$.
Recall that, for all $1\leq j\leq N$, $|V(C_j)|=N^{i-1}$, and the number of center vertices in $C_j$ is $N^{i-2}$. Therefore, we get that $|V_i|=N^i$ and the number of center vertices in $W_i$ is $N^{i-1}$, as required.

For all $1\leq i'<i$, the set $E^i_{i'}$ of level-$i'$ edges of $W_i$ is the union of the sets of level-$i'$ edges of $C_1,\ldots,C_N$. It now remains to define the set $E_i^i$ of level-$i$ edges for graph $W_i$.
In order to do so, we will construct a collection $\sset_i$ of $N^{i-1}$ disjoint stars, where each star $S\in \sset_i$ contains exactly one vertex from each of the clusters $C_1,\ldots,C_N$, and the center of the star lies in $V_i^c$. The set $E_i^i$ of level-$i$ edges is then  obtained by replacing each edge $e\in \bigcup_{S\in \sset_i}E(S)$ with  $\Delta$ parallel edges.

In order to construct the collection $\sset_i$ of stars, we first define, for each $1\leq j\leq N$, an ordering $v^j_1,\ldots,v^j_{N^{i-1}}$ of the vertices of $C_j$, such that, for all $1\leq z\leq N^{i-1}$, if we consider the vertices $ v^1_z,\ldots,v^N_z$ (that is, the vertices that appear in the $z$th position in the orderings of $V(C_1),\ldots,V(C_N)$), then exactly one of these vertices is a center vertex in $V^c_i$.

 Such orderings are easy to define: consider the collection $I=\set{1,\ldots,N^{i-1}}$ of indices, and partition it into $N$ disjoint subsets $I_1,\ldots,I_N$, each of which contains exactly $N^{i-2}$ contiguous indices.
  For each $1\leq j\leq N$, we order the vertices of $C_j$ arbitrarily, but we ensure that the center vertices of $C_j$ lie in the positions whose indices belong to $I_j$ in this ordering. This ensures that, for all $1\leq z\leq N^{i-1}$, exactly one vertex that lies in the $z$th position in the orderings of $C_1,\ldots,C_N$ is a center vertex.

 For all $1\leq z\leq N^{i-1}$, we let $S_z$ be the star that consists of the vertices $\set{v^1_z,\ldots,v^N_z}$, where the center of the star is the unique vertex $v^j_z$ that lies in $V_i^c$. Then for every edge $(x,y)$ of the star $S_z$, we create $\Delta$ parallel edges $(x,y)$, which are added to set $E^i_i$. These parallel edges are called a \emph{bundle}, and the edge of the star corresponding to them is called a \emph{superedge}.
 We denote by $\sset_i=\set{S_1,\ldots,S_{N^{i-1}}}$ the resulting collection of level-$i$ stars. This completes the construction of the set $E^i_i$ of level-$i$ edges of graph $W_i$. Lastly, we let $E(W_i)=\bigcup_{i'=1}^NE^i_{i'}$, completing the construction of the graph $W_i$. For all $1\leq i'<i$, the collection $\sset_{i'}$ of level-$i'$ stars is the union of the collections of level-$i'$ stars of the graphs $C_1,\ldots,C_N$.

Consider now the level-$k$ graph $W_k$. For all $1\leq i<k$, graph $W_k$ contains $N^{k-i}$ copies of the level-$i$ graph $W_i$. We let $\cset_i$ denote the partition of the vertices of $W_k$ defined by these copies of $W_i$. We refer to $\cset_i$ as \emph{level-$i$ clustering}, and we refer to each subgraph $C\in \cset_i$ as a \emph{level-$i$ cluster}. Notice that for all $1\leq i<k$, each level-$i$ cluster is contained in a single level-$(i+1)$ cluster, and moreover, each level-$(i+1)$ cluster contains the union of exactly $N$ level-$i$ clusters. There is a single level-$k$ cluster, containing all vertices of $W_k$. From our construction, it is easy to verify that, for all $1\leq i\leq k$, if we denote by $H_i=W_k[E^k_i]$ the subgraph of $W_k$ induced by the level-$i$ edges, then there is a collection $\sset_i$ of $N^{k-1}$ disjoint star graphs, where each star $S\in \sset_i$ has $N$ vertices, and the center of $S$ lies in $V_k^c$, such that the set $E^k_i$ of edges can be obtained from $E'_i=\bigcup_{S\in \sset_i}E(S)$, by replacing each edge $e\in E'_i$ with $\Delta$ parallel edges. We refer to the set $\sset_i$ of stars as \emph{level-$i$ stars}. Lastly, note that for all $1\leq i\leq k$, the number of level-$i$ superedges in $W_k$ is at most $N^k$, and $|E^k_i|\leq \Delta\cdot N^k$. Overall, $W_k$ contains at most $k\cdot N^k$ superedges, and $|E(W_k)|\leq k\cdot \Delta\cdot N^k$. Moreover, the degree of every center vertex in $W_k$ is exactly $(N-1)\cdot \Delta \cdot k$, and the degree of every leaf vertex is exactly $\Delta\cdot k$.

\subsection{Properly Pruned Subgraphs of $W_k$}
\label{subsec: properly pruned}

\begin{definition}\label{def: properly pruned}
	For $1\leq i\leq k$, a subgraph $W\subseteq W_i$ is a \emph{properly pruned} subgraph of $W_i$ with respect to  sets $U_1,U_2,\ldots,U_i\subseteq V(W_i)$ of its vertices, where $U_i\subseteq U_{i-1}\subseteq\cdots\subseteq U_1$, if the following hold:

	\begin{properties}{P}
		\item for every level $1\leq i'\leq i$, for every leaf vertex $v\in V^{\ell}_{i}$:\label{prop: leaf vertices}
		\begin{itemize}
			\item if $v\in U_{i'}$, then at least $\ceil{\Delta/2}$ level-$i'$ edges that are incident to $v$ in $W_i$ lie in $W$ (recall that all these edges must be parallel edges that correspond to the unique level-$i'$ superedge that is incident to $v$);
			\item otherwise, $W$ contains no level-$i'$ edges that are incident to $v$; 
		\end{itemize}
	\item for each level $1\leq i'\leq i$, for every center vertex $v\in V^{c}_{i}$, if we denote by $S\in \sset_{i'}$ the unique level-$i'$ star for which $v$ serves as a center, then:\label{prop: center vertices}

	\begin{itemize}
		\item if $v\in U_{i'}$, then at least $N\cdot \left(1-\frac{1}{k}\right )$ leaf vertices of $S$ lie in $U_{i'}$ (and we say that star $S$ \emph{survives} in this case); 
		\item otherwise, no leaf vertices of $S$ lie in $U_{i'}$ (and we say that star $S$ is \emph{destroyed}); 
	\end{itemize}

\item $V(W)=U_1$; \label{prop: U1 is all vertices} and
\item for every level $1\leq i'<i$, for every level-$i'$ cluster $C\in \cset_{i'}$ of $W_i$, either $V(C)\cap U_1=\emptyset$ (in which case we say that cluster $C$ is \emph{destroyed}), or at least $\frac{|V(C)|}{k^{3k}}$ vertices of $C$ lie in $U_{i'+1}$ (and we say that cluster $C$ \emph{survives}). \label{prop: cluster survival}
\end{properties}
\end{definition}

\subsection{Routing in Properly Pruned Subgraphs of $W_k$}
\label{subsec: routing in properly pruned}

\begin{theorem}\label{thm: pruning to routing}
	Let $W$ be a properly pruned subgraph of $W_k$, with respect to sets $U_1,\ldots,U_k$ of its vertices, and let $\dset=\left (\Pi,\set{D(a,b)}_{(a,b)\in \Pi}\right )$ be a  $\frac{\Delta}{k^{4k}}$-restricted demand  for $W$. Then there is a fractional routing of $\dset$ in $W$ with no edge-congestion, such that every flow-path $P$ with $f(P)>0$ has length at most $20k^2$.	Moreover, there is an algorithm, that, given the graph $W$, the sets $U_1,\ldots,U_k$ of its vertices, and the demand $\dset$, computes such a routing in time  $O\left (k^2\cdot\Delta\cdot N\cdot (N^k+|\Pi|)\right )$.
\end{theorem}

\section{Third Tool: Router Witness}
\label{sec: router witness}

\subsection{A Sparsified Router}
\label{subsec: sparsified router}

In this subsection we assume that we are given a simple graph $C$, together with parameters $1\leq \Delta^*\leq \Delta$.
Assume further that we are given another graph $W$, that is a properly pruned subgraph of $W^{N,\Delta}_k$, for some parameters $N$ and $k$, together with an embedding $\pset$ of $W$ into $C$ via paths of length at most $d^*$, that cause congestion at most $\eta^*$, such that every vertex $v\in V(C)$ lies on at least $\floor{\frac{\Delta^*}{2kd^*}}$ paths in $\pset$. Finally, assume that $\Delta^*\geq 2kd^*$.

We use a parameter $\Delta'=\floor{\frac{\Delta^*}{2kd^*}}$. In order to construct a sparsified router $C'$ for $C$, we select, for every superedge $(u,v)$ of $W$, an arbitrary collection $E'(u,v)\subseteq E(W)$ of $\Delta'$ parallel edges (recall that, from \Cref{def: properly pruned}, graph $W$ must contain at least $\frac{\Delta}{2}\geq \frac{\Delta^*}{2}\geq \Delta'$ such parallel edges). Let $W'\subseteq W$ be the graph obtained from $W$ by including, for every superedge $(u,v)$ of $W$, only the edges of $E'(u,v)$. Additionally, for every vertex $v\in V(C)$, we select an arbitrary subset $\pset(v)\subseteq \pset$ of $\Delta'$ paths that contain $v$, such that every leaf vertex $u\in V(W)$ serves as an endpoint in at most $\gamma\cdot \Delta'$ paths in the multiset $\bigcup_{v\in V(C)}\pset(v)$, for some parameter $\gamma$.  (Whenever using this tool, we will provide an explicit algorithm for constructing and maintaining the sets $\pset(v)$ of paths for vertices $v\in V(C)$).

We let $C'\subseteq C$ be the simple graph obtained by taking the union of all paths in $\bigcup_{v\in V(C)}\pset(v)$, and all paths of $\pset$ that serve as embedding paths for the  edges in $E(W')$.
